import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let a = 1
    let n: Int8 = if a > 0 { 3i8 } else { 1i8 }
    let m: Int8 = if a > 0 { 2i8 } else { 1i8 }
    let y: Int8 = n + m
    if y == 5i8 {
        io.println("five")
    }
    return Ok(())
}
